    g = [row[:] for row in grid]
    # Interior of the green rectangular frame is filled with 4; add the
    # nested square motif around the lone green seed.
    coords = [(r, c) for r, row in enumerate(g) for c, v in enumerate(row) if v == 3]
    # Keep original frame and identify the isolated 3 inside it.
    frame_rows = [r for r, row in enumerate(g) if any(v == 3 for v in row)]
    frame_cols = [c for c in range(len(g[0])) if any(g[r][c] == 3 for r in range(len(g)))]
    r0, r1 = min(frame_rows), max(frame_rows)
    c0, c1 = min(frame_cols), max(frame_cols)
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            g[r][c] = 4
    seed = next((r, c) for r, c in coords if r0 < r < r1 and c0 < c < c1)
    sr, sc = seed
    for dr in range(-2, 3):
        for dc in range(-2, 3):
            r, c = sr + dr, sc + dc
            if r0 < r < r1 and c0 < c < c1:
                if max(abs(dr), abs(dc)) == 2:
                    g[r][c] = 2
                elif max(abs(dr), abs(dc)) == 1:
                    g[r][c] = 4
                else:
                    g[r][c] = 3
    return g
